INSERT OR IGNORE INTO beat_items (id, source, source_tier, author_account, team_slug, league, category, headline, context, original_url, embed_url, embed_id, oembed_html, timestamp, media_type, verified_official, expires_at, approval_status, approval_mode, approved_by, approved_at, pinned, relevance_score, duplicate_fingerprint, created_at, updated_at, created_by) VALUES ('beat-m2-seed-01', 'Pro Football Rumors (citing Mike Garafolo, NFL Network)', 'reporter_original', 'Pro Football Rumors (citing Mike Garafolo, NFL Network)', 'steelers', 'NFL', 'breaking', 'Steelers have made an offer to Joey Porter Jr.; deal not imminent ahead of Week 1', 'NFL Network’s Mike Garafolo reported the Steelers submitted an extension offer to CB Joey Porter Jr. ahead of Sunday’s home opener vs. Atlanta, with the sides still not close. Pittsburgh historically stops negotiating once the regular season begins; Porter missed camp with a back injury and was limited in Wednesday practice. Coach Mike McCarthy was noncommittal Thursday on Porter’s practice/Week 1 status.', 'https://www.profootballrumors.com/2026/09/steelers-have-made-offer-to-joey-porter-jr-deal-not-imminent', NULL, NULL, NULL, '2026-09-10T12:00:00.000Z', 'link_out', 0, '2026-09-15T03:59:00.000Z', 'approved', 'manual', 'seed:m2', '2026-09-10T18:00:00.000Z', 1, NULL, 'url:https://www.profootballrumors.com/2026/09/steelers-have-made-offer-to-joey-porter-jr-deal-not-imminent', '2026-09-10T18:00:00.000Z', '2026-09-10T18:00:00.000Z', 'seed:m2');

INSERT OR IGNORE INTO beat_items (id, source, source_tier, author_account, team_slug, league, category, headline, context, original_url, embed_url, embed_id, oembed_html, timestamp, media_type, verified_official, expires_at, approval_status, approval_mode, approved_by, approved_at, pinned, relevance_score, duplicate_fingerprint, created_at, updated_at, created_by) VALUES ('beat-m2-seed-02', 'The Philadelphia Inquirer', 'broadcaster_publication', 'The Philadelphia Inquirer', 'eagles', 'NFL', 'locker_room', 'Hurts backs Mannion calling plays from the booth for Week 1 vs. Commanders', 'Nick Sirianni said Wednesday that first-year OC Sean Mannion will “probably” call plays from the coaching box for Sunday’s home opener against Washington. Jalen Hurts said he hasn’t had a booth play-caller since college and will support whatever helps Mannion feel comfortable, citing red-phone communication between drives.', 'https://www.inquirer.com/eagles/jalen-hurts-sean-mannion-coaching-box-2026-season-opener-20260909.html', NULL, NULL, NULL, '2026-09-10T12:00:00.000Z', 'link_out', 0, '2026-09-15T03:59:00.000Z', 'approved', 'manual', 'seed:m2', '2026-09-10T18:00:00.000Z', 0, NULL, 'url:https://www.inquirer.com/eagles/jalen-hurts-sean-mannion-coaching-box-2026-season-opener-20260909.html', '2026-09-10T18:00:00.000Z', '2026-09-10T18:00:00.000Z', 'seed:m2');

INSERT OR IGNORE INTO beat_items (id, source, source_tier, author_account, team_slug, league, category, headline, context, original_url, embed_url, embed_id, oembed_html, timestamp, media_type, verified_official, expires_at, approval_status, approval_mode, approved_by, approved_at, pinned, relevance_score, duplicate_fingerprint, created_at, updated_at, created_by) VALUES ('beat-m2-seed-03', 'Bleeding Green Nation', 'broadcaster_publication', 'Bleeding Green Nation', 'eagles', 'NFL', 'from_the_beat', 'Eagles Week 1 injury report: Greenard (pectoral) and Stowers (hamstring) limited', 'Philadelphia’s first 2026 regular-season injury report listed EDGE Jonathan Greenard (pectoral) and TE Eli Stowers (hamstring) as limited Wednesday, with zero DNPs. Greenard returned after missing training camp; the Inquirer’s Jeff McLane noted the club wants to see how he practices before deciding Sunday availability vs. Washington.', 'https://www.bleedinggreennation.com/news/182210/eagles-injury-report-jonathan-greenard-and-eli-stowers-limited', NULL, NULL, NULL, '2026-09-10T12:00:00.000Z', 'link_out', 0, '2026-09-15T00:00:00.000Z', 'approved', 'manual', 'seed:m2', '2026-09-10T18:00:00.000Z', 0, NULL, 'url:https://www.bleedinggreennation.com/news/182210/eagles-injury-report-jonathan-greenard-and-eli-stowers-limited', '2026-09-10T18:00:00.000Z', '2026-09-10T18:00:00.000Z', 'seed:m2');

INSERT OR IGNORE INTO beat_items (id, source, source_tier, author_account, team_slug, league, category, headline, context, original_url, embed_url, embed_id, oembed_html, timestamp, media_type, verified_official, expires_at, approval_status, approval_mode, approved_by, approved_at, pinned, relevance_score, duplicate_fingerprint, created_at, updated_at, created_by) VALUES ('beat-m2-seed-04', 'Philadelphia Phillies (@Phillies)', 'official_team_league', '@Phillies', 'phillies', 'MLB', 'reaction', 'Official X: “KYLE SCHWARBER GRAND SLAM!!”', 'Verified official Phillies post from Sept. 10, 2026 celebrating Kyle Schwarber’s grand slam in Wednesday’s 11–7 comeback win over Houston. Schwarber’s blast was his MLB-leading 44th home run and 10th career grand slam, capping a six-run sixth.', 'https://x.com/Phillies/status/2097848487366824203', 'https://x.com/i/status/2097848487366824203', '2097848487366824203', NULL, '2026-09-10T12:00:00.000Z', 'x_embed', 1, '2026-09-18T03:59:00.000Z', 'approved', 'manual', 'seed:m2', '2026-09-10T18:00:00.000Z', 0, NULL, 'x:2097848487366824203', '2026-09-10T18:00:00.000Z', '2026-09-10T18:00:00.000Z', 'seed:m2');

INSERT OR IGNORE INTO beat_items (id, source, source_tier, author_account, team_slug, league, category, headline, context, original_url, embed_url, embed_id, oembed_html, timestamp, media_type, verified_official, expires_at, approval_status, approval_mode, approved_by, approved_at, pinned, relevance_score, duplicate_fingerprint, created_at, updated_at, created_by) VALUES ('beat-m2-seed-05', 'Philadelphia Phillies YouTube', 'official_team_league', 'phillies', 'phillies', 'MLB', 'watch', 'Official YouTube: Schwarber’s 10th career grand slam vs. Astros (full at-bat)', 'Official Phillies channel upload of Kyle Schwarber’s grand slam at-bat against Houston on Sept. 9, 2026. Companion full-game highlights also available on the same channel (Astros vs. Phillies Game Highlights 9/9/26).', 'https://www.youtube.com/watch?v=v3l96WUeXvs', 'https://www.youtube-nocookie.com/embed/v3l96WUeXvs', 'v3l96WUeXvs', NULL, '2026-09-10T18:00:00.000Z', 'youtube_embed', 1, NULL, 'approved', 'manual', 'seed:m2', '2026-09-10T18:00:00.000Z', 0, NULL, 'yt:v3l96WUeXvs', '2026-09-10T18:00:00.000Z', '2026-09-10T18:00:00.000Z', 'seed:m2');

INSERT OR IGNORE INTO beat_items (id, source, source_tier, author_account, team_slug, league, category, headline, context, original_url, embed_url, embed_id, oembed_html, timestamp, media_type, verified_official, expires_at, approval_status, approval_mode, approved_by, approved_at, pinned, relevance_score, duplicate_fingerprint, created_at, updated_at, created_by) VALUES ('beat-m2-seed-06', 'Philadelphia Union (official site)', 'official_team_league', 'PhilaUnion', 'union', 'MLS', 'reaction', 'Union 5–0 FC Cincinnati: Damiani hat trick; Sullivan brothers combine', 'Official club box score from Wednesday’s Subaru Park win: Quinn Sullivan (PK), Bruno Damiani hat trick with assists from Cavan/Quinn Sullivan, Milan Iloski PK. Notes list a nine-match MLS unbeaten run and the Sullivans as the third brother pair in MLS history with assists on the same goal. Next: at San Diego FC Sunday 9 p.m. ET on Apple TV.', 'https://www.philadelphiaunion.com/news/box-score-philadelphia-union-5-fc-cincinnati-0', NULL, NULL, NULL, '2026-09-10T12:00:00.000Z', 'link_out', 1, '2026-09-15T03:59:00.000Z', 'approved', 'manual', 'seed:m2', '2026-09-10T18:00:00.000Z', 0, NULL, 'url:https://www.philadelphiaunion.com/news/box-score-philadelphia-union-5-fc-cincinnati-0', '2026-09-10T18:00:00.000Z', '2026-09-10T18:00:00.000Z', 'seed:m2');

INSERT OR IGNORE INTO beat_items (id, source, source_tier, author_account, team_slug, league, category, headline, context, original_url, embed_url, embed_id, oembed_html, timestamp, media_type, verified_official, expires_at, approval_status, approval_mode, approved_by, approved_at, pinned, relevance_score, duplicate_fingerprint, created_at, updated_at, created_by) VALUES ('beat-m2-seed-07', 'Philadelphia Flyers / NHL.com', 'official_team_league', 'NHLFlyers', 'flyers', 'NHL', 'watch', 'Flyers 2026 Rookie Camp opens Friday at PPL Center vs. Rangers rookies', 'Official Flyers release: Rookie Camp on-ice sessions begin Friday, Sept. 11 at PPL Center (Allentown), with games vs. New York Rangers rookies Saturday 7:05 p.m. and Sunday 5:05 p.m. ET, streamed on PhiladelphiaFlyers.com. Main training camp opens Sept. 17.', 'https://www.nhl.com/flyers/news/flyers-announce-2026-rookie-camp-roster-and-schedule', NULL, NULL, NULL, '2026-09-10T12:00:00.000Z', 'link_out', 1, '2026-09-15T03:59:00.000Z', 'approved', 'manual', 'seed:m2', '2026-09-10T18:00:00.000Z', 0, NULL, 'url:https://www.nhl.com/flyers/news/flyers-announce-2026-rookie-camp-roster-and-schedule', '2026-09-10T18:00:00.000Z', '2026-09-10T18:00:00.000Z', 'seed:m2');

INSERT OR IGNORE INTO beat_items (id, source, source_tier, author_account, team_slug, league, category, headline, context, original_url, embed_url, embed_id, oembed_html, timestamp, media_type, verified_official, expires_at, approval_status, approval_mode, approved_by, approved_at, pinned, relevance_score, duplicate_fingerprint, created_at, updated_at, created_by) VALUES ('beat-m2-seed-08', 'Onward State', 'broadcaster_publication', 'Onward State', 'penn-state', 'NCAAF', 'from_the_beat', 'No. 16 Penn State heavy favorites at Temple (Lincoln Financial Field) Saturday', 'After a 45–0 Week 1 win over Marshall in Matt Campbell’s debut, Penn State is a 24.5-point favorite at Temple on Saturday, Sept. 12 at noon at Lincoln Financial Field. Onward State notes the series history (PSU 40-4-1) and Temple’s last win over PSU coming at the Linc in 2015.', 'https://onwardstate.com/2026/09/10/penn-state-football-favorited-over-temple-at-lincoln-financial-field/', NULL, NULL, NULL, '2026-09-10T12:00:00.000Z', 'link_out', 0, '2026-09-12T22:00:00.000Z', 'approved', 'manual', 'seed:m2', '2026-09-10T18:00:00.000Z', 0, NULL, 'url:https://onwardstate.com/2026/09/10/penn-state-football-favorited-over-temple-at-lincoln-financial-field', '2026-09-10T18:00:00.000Z', '2026-09-10T18:00:00.000Z', 'seed:m2');

INSERT OR IGNORE INTO beat_items (id, source, source_tier, author_account, team_slug, league, category, headline, context, original_url, embed_url, embed_id, oembed_html, timestamp, media_type, verified_official, expires_at, approval_status, approval_mode, approved_by, approved_at, pinned, relevance_score, duplicate_fingerprint, created_at, updated_at, created_by) VALUES ('beat-m2-seed-09', 'Pitt Athletics (pittsburghpanthers.com)', 'official_team_league', 'Pitt_FB', 'pitt', 'NCAAF', 'reaction', 'Mason Heintschel named Maxwell and Davey O’Brien national weekly honoree', 'Official Pitt release (Sept. 9): After a 59–14 opener vs. Miami (OH), QB Mason Heintschel (31-of-41, 453 yards, 7 TDs, 0 INT) earned Maxwell Award Player of the Week and Davey O’Brien National Quarterback of the Week. Pitt hosts UCF Saturday at 3:30 p.m. at Acrisure Stadium.', 'https://pittsburghpanthers.com/news/2026/9/9/football-heintschel-earns-maxwell-davey-o-brien-national-weekly-honors', NULL, NULL, NULL, '2026-09-10T12:00:00.000Z', 'link_out', 1, '2026-09-14T03:59:00.000Z', 'approved', 'manual', 'seed:m2', '2026-09-10T18:00:00.000Z', 0, NULL, 'url:https://pittsburghpanthers.com/news/2026/9/9/football-heintschel-earns-maxwell-davey-o-brien-national-weekly-honors', '2026-09-10T18:00:00.000Z', '2026-09-10T18:00:00.000Z', 'seed:m2');

